  let currentSpreadIdx = 0;

  function padZero(num) {
    return num < 10 ? '0' + num : '' + num;
  }

  function goToSpread(idx) {
    if (idx < 0 || idx >= archiveSpreads.length) return;
    currentSpreadIdx = idx;
    const imgEl = document.getElementById('s5MainImg');
    imgEl.style.opacity = '0.35';
    setTimeout(() => {
      imgEl.src = archiveSpreads[idx].src;
      imgEl.alt = archiveSpreads[idx].title;
      imgEl.style.opacity = '1';
    }, 90);

    const pageLabel = padZero(idx + 1) + ' / ' + padZero(archiveSpreads.length);
    document.getElementById('s5PageIndicator').textContent = pageLabel;
    document.getElementById('s5ZoomPageTxt').textContent = pageLabel;

    document.getElementById('s5PrevBtn').disabled = (idx === 0);
    document.getElementById('s5NextBtn').disabled = (idx === archiveSpreads.length - 1);

    const thumbs = document.querySelectorAll('.s5-thumb-item');
    thumbs.forEach((btn, i) => {
      btn.classList.toggle('active', i === idx);
      if (i === idx) {
        btn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
    });
  }

  function changeSpread(delta) {
    goToSpread(currentSpreadIdx + delta);
  }

  /* Zoom & Pan Controller */
  let zoomScale = 1;
  let panX = 0;
  let panY = 0;
  let isDragging = false;
  let dragStartX = 0;
  let dragStartY = 0;
  let initialPinchDist = 0;
  let initialPinchScale = 1;

  function updateZoomTransform() {
    const zImg = document.getElementById('s5ZoomImg');
    zImg.style.transform = `translate(${panX}px, ${panY}px) scale(${zoomScale})`;
    zImg.classList.toggle('is-zoomed', zoomScale > 1);
    document.getElementById('s5ZoomLevel').textContent = Math.round(zoomScale * 100) + '%';
  }

  function resetZoom() {
    zoomScale = 1;
    panX = 0;
    panY = 0;
    updateZoomTransform();
  }

  function stepZoom(delta) {
    zoomScale = Math.min(4, Math.max(1, zoomScale + delta));
    if (zoomScale === 1) {
      panX = 0;
      panY = 0;
    }
    updateZoomTransform();
  }

  function openSpreadZoom() {
    const item = archiveSpreads[currentSpreadIdx];
    const zImg = document.getElementById('s5ZoomImg');
    zImg.src = item.src;
    zImg.alt = item.title;
    resetZoom();
    document.getElementById('s5ZoomModal').classList.add('open');
    document.body.style.overflow = 'hidden';
  }

  function closeSpreadZoom() {
    document.getElementById('s5ZoomModal').classList.remove('open');
    document.body.style.overflow = '';
    resetZoom();
  }

  (function() {
    const stage = document.getElementById('s5Stage');
    let touchStartX = 0;
    let touchEndX = 0;

    stage.addEventListener('touchstart', function(e) {
      touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });

    stage.addEventListener('touchend', function(e) {
      touchEndX = e.changedTouches[0].screenX;
      const diff = touchStartX - touchEndX;
      if (Math.abs(diff) > 40) {
        if (diff > 0) changeSpread(1);
        else changeSpread(-1);
      }
    }, { passive: true });

    const zoomCanvas = document.getElementById('s5ZoomCanvas');
    const zoomImg = document.getElementById('s5ZoomImg');

    let movedDuringClick = false;
    zoomImg.addEventListener('mousedown', function(e) {
      if (zoomScale <= 1) return;
      isDragging = true;
      movedDuringClick = false;
      dragStartX = e.clientX - panX;
      dragStartY = e.clientY - panY;
      zoomImg.classList.add('is-dragging');
      e.preventDefault();
    });

    window.addEventListener('mousemove', function(e) {
      if (!isDragging) return;
      movedDuringClick = true;
      panX = e.clientX - dragStartX;
      panY = e.clientY - dragStartY;
      updateZoomTransform();
    });

    window.addEventListener('mouseup', function() {
      if (isDragging) {
        isDragging = false;
        zoomImg.classList.remove('is-dragging');
      }
    });

    zoomImg.addEventListener('click', function(e) {
      e.stopPropagation();
      if (movedDuringClick) {
        movedDuringClick = false;
        return;
      }
      if (zoomScale === 1) {
        zoomScale = 2.2;
      } else {
        resetZoom();
      }
      updateZoomTransform();
    });

    zoomCanvas.addEventListener('click', function(e) {
      if (e.target === zoomCanvas) closeSpreadZoom();
    });

    zoomCanvas.addEventListener('wheel', function(e) {
      e.preventDefault();
      const delta = e.deltaY < 0 ? 0.35 : -0.35;
      stepZoom(delta);
    }, { passive: false });

    zoomCanvas.addEventListener('touchstart', function(e) {
      if (e.touches.length === 2) {
        initialPinchDist = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        initialPinchScale = zoomScale;
      } else if (e.touches.length === 1 && zoomScale > 1) {
        isDragging = true;
        dragStartX = e.touches[0].clientX - panX;
        dragStartY = e.touches[0].clientY - panY;
        zoomImg.classList.add('is-dragging');
      }
    }, { passive: true });

    zoomCanvas.addEventListener('touchmove', function(e) {
      if (e.touches.length === 2) {
        e.preventDefault();
        const dist = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        if (initialPinchDist > 0) {
          zoomScale = Math.min(4, Math.max(1, initialPinchScale * (dist / initialPinchDist)));
          if (zoomScale === 1) {
            panX = 0;
            panY = 0;
          }
          updateZoomTransform();
        }
      } else if (e.touches.length === 1 && isDragging && zoomScale > 1) {
        e.preventDefault();
        panX = e.touches[0].clientX - dragStartX;
        panY = e.touches[0].clientY - dragStartY;
        updateZoomTransform();
      }
    }, { passive: false });

    zoomCanvas.addEventListener('touchend', function() {
      isDragging = false;
      zoomImg.classList.remove('is-dragging');
    }, { passive: true });

    document.addEventListener('keydown', function(e) {
      const modalOpen = document.getElementById('s5ZoomModal').classList.contains('open');
      if (e.key === 'Escape' && modalOpen) {
        closeSpreadZoom();
        return;
      }
      if (!modalOpen) {
        if (e.key === 'ArrowLeft') changeSpread(-1);
        if (e.key === 'ArrowRight') changeSpread(1);
      }
    });

    goToSpread(0);
  })();